// Подпись поля даты работы/лида: «Date» / HE «תאריך» вместо «Scheduled Date» (#6d5cda04). Только просмотр — ничего не вводим
// (Job Details автосохраняет).
import { expect, Locator, Page } from '@playwright/test';

export const LABEL = {
  en: { date: /^date$/i, completedTab: 'Completed', preview: 'Preview', dateLine: 'Date' },
  he: { date: /^תאריך$/, completedTab: 'הסתיימו', preview: 'תצוגה מקדימה', dateLine: 'תאריך' },
} as const;
export type Lang = keyof typeof LABEL;

/** Работа для Job Details / превью (клиент «test», Completed). */
export const VIEW_JOB = 'JOB-0011';

/** Старая подпись нигде в области (EN, любой регистр — в New Job подписи капсом через CSS). */
export async function expectNoScheduledDate(area: Locator, where: string) {
  const text = await area.innerText();
  expect(text, `${where}: осталось «Scheduled Date»`).not.toMatch(/scheduled\s*date/i);
}

/** Подпись поля даты видна ровно одна. */
export async function expectDateLabel(page: Page, lang: Lang, where: string) {
  const label = page.locator('label:visible').filter({ hasText: LABEL[lang].date });
  await expect(label, `${where}: подпись «${LABEL[lang].dateLine}»`).toHaveCount(1);
}

/** /jobs → вкладка Completed → строка работы. */
export async function openCompletedRow(page: Page, lang: Lang, jobId: string): Promise<Locator> {
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText('JOB-00');
  await page.getByRole('tab', { name: LABEL[lang].completedTab, exact: true }).click();
  const row = page.locator('tr', { hasText: jobId }).first();
  await expect(row).toBeVisible();
  return row;
}
